package main
import("context";"database/sql";"fmt";"time";_ "github.com/go-sql-driver/mysql")
func main(){db,e:=sql.Open("mysql","bridge:BridgeDb-e9a3797e70b64888@tcp(bridge_mysql:3306)/bridge?parseTime=true&charset=utf8mb4");fmt.Println("open",e); ctx,c:=context.WithTimeout(context.Background(),5*time.Second);defer c();fmt.Println("ping",db.PingContext(ctx)); tx,e:=db.BeginTx(ctx,nil);fmt.Println("begin",e); rows,e:=tx.QueryContext(ctx,"SELECT id,event_id,target_system,message_json,status,attempts,next_attempt_at,last_error,created_at,updated_at FROM bridge_outbox_job WHERE status IN ('pending','retry') AND next_attempt_at<=? ORDER BY created_at,id LIMIT 100 FOR UPDATE",time.Now().Unix());fmt.Printf("query=%v rows=%v\n",e,rows);if rows!=nil{rows.Close()};fmt.Println("commit",tx.Commit())}
